import { Group, PlaneGeometry, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec4, mix, float, positionView, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Geometry ---
  // Source rect suggests 512x320 → aspect ~1.6 : 1
  const aspect = 512 / 320; // ~1.6
  const width = 1.6;
  const height = 1.0;
  const geometry = new PlaneGeometry(width, height);

  // --- Material with gradient overlay ---
  // Colors from spec: surface #0b0b10, paper #e8ecf2
  const surfaceColor = new Float32Array([0.043, 0.043, 0.063]); // #0b0b10
  const paperColor   = new Float32Array([0.909, 0.925, 0.949]); // #e8ecf2

  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });

  // Set up texture loading (async)
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // Build shader nodes for gradient overlay
  const texNode = uniform(); // placeholder, will be replaced when texture loads
  const gradient = mix(vec4(surfaceColor[0], surfaceColor[1], surfaceColor[2], 1),
                       vec4(paperColor[0], paperColor[1], paperColor[2], 1),
                       uv.y.add(0.3).mul(0.6).clamp(0, 1)); // subtle vertical gradient

  // Combine texture and gradient
  const finalColor = mix(texNode, gradient, float(0.15)); // 15% gradient overlay
  material.colorNode = finalColor;

  // Create mesh
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Assign position/rotation/scale from config (scenePosition will be applied externally)
  // But we set position from config.scenePosition if available
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }

  // Handle texture load
  texturePromise.then((tex) => {
    texNode.value = tex; // update the uniform node
    material.needsUpdate = true;
  });

  // --- User data ---
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
